<script setup lang="ts">
import type { BsAccountClassificationCopy, BsAccountClassificationForm, BsAccountClassificationView } from '../types/financialAccountsPresentation'
defineProps<{ copy: BsAccountClassificationCopy; view: BsAccountClassificationView }>()
const form = defineModel<BsAccountClassificationForm>('form', { required: true })
const emit = defineEmits<{ close: []; save: []; retry: [] }>()
function field<K extends keyof BsAccountClassificationForm>(key: K, value: string) { form.value = { ...form.value, [key]: value } }
</script>
<template>
 <BsRecordActionDialog :visible="view.visible" :title="copy.title" size="lg" :dirty="view.dirty" :pending="view.pending" :error="view.error" :submit-label="copy.schedule" :cancel-label="copy.cancel" :submit-disabled="view.submitDisabled" @update:visible="value => { if (!value) emit('close') }" @submit="emit('save')"><BsText emphasis="semibold">{{ view.name }}</BsText><BsFloatingField :label="copy.dimension"><BsSelect :model-value="form.dimension" :label="copy.dimension" :disabled="view.pending" :options="view.dimensions" option-label="label" option-value="value" native @update:model-value="field('dimension', String($event))"/></BsFloatingField><BsText size="sm" tone="muted">{{ copy.hint }}</BsText><BsSectionSkeleton v-if="view.loading" variant="table" :rows="3"/><template v-else><BsButton v-if="view.error" :disabled="view.pending" @click="emit('retry')">{{ copy.retry }}</BsButton><template v-if="view.hasContext"><BsText v-if="!view.canSchedule" size="sm" tone="muted">{{ copy.readOnly }}</BsText><BsStack v-else gap="md"><BsFloatingField :label="copy.line"><BsSelect id="statement-line" :model-value="form.statementLine" :label="copy.line" required :disabled="view.pending" :options="view.lines" option-label="label" option-value="value" native @update:model-value="field('statementLine', String($event))"/></BsFloatingField><BsFloatingField :label="copy.effective"><BsInput id="statement-effective" :model-value="form.effectiveFrom" type="date" required :min="view.minDate" :disabled="view.pending" @update:model-value="field('effectiveFrom', String($event ?? ''))"/></BsFloatingField><BsText size="sm" tone="muted">{{ view.minimum }}</BsText><BsFloatingField :label="copy.reason"><BsTextarea id="statement-reason" :model-value="form.reason" :rows="3" required :maxlength="1000" :disabled="view.pending" @update:model-value="field('reason', String($event ?? ''))"/></BsFloatingField></BsStack><BsHeading :level="3" size="body">{{ copy.history }}</BsHeading><BsText v-if="!view.history.length" size="sm" tone="muted">{{ copy.noHistory }}</BsText><BsDataTable v-else :value="view.history" data-key="id" :label="copy.history" :paginator="view.history.length > 10" :rows="10" :columns="[{ key: 'effective', field: 'effective', header: copy.effective }, { key: 'line', field: 'line', header: copy.line }, { key: 'reason', field: 'reason', header: copy.reason }]"/></template></template></BsRecordActionDialog>
</template>
